style.css:
@-moz-document domain("anime-sama.to") {
/* =========================================================
   ANIME-SAMA V4 — GOLD / BLACK / CINEMATIC
   calibré pour la vraie home Anime-Sama
   ========================================================= */

:root{
  --bg-image: url("https://i.pinimg.com/1200x/7a/fd/79/7afd79c6fd018ec6023dc109945e5781.jpg");

  --bg0:#050505;
  --bg1:#0b0b0f;
  --bg2:#121218;
  --bg3:#181821;

  --glass: rgba(10,10,12,.58);
  --glass2: rgba(14,14,18,.68);
  --glass3: rgba(18,18,24,.44);
  --glassSoft: rgba(10,10,12,.34);

  --gold:#f6c76e;
  --gold2:#ffd27f;
  --gold3:#e3ad55;
  --orange:#ff8b47;
  --copper:#d56d2d;

  --text:#f8f3ea;
  --textSoft:#ddd3c6;
  --muted:#b7ad9e;

  --border: rgba(255,201,110,.16);
  --borderStrong: rgba(255,201,110,.30);

  --shadowDark: 0 18px 46px rgba(0,0,0,.40);
  --shadowGlow: 0 0 24px rgba(255,191,95,.08);

  --radiusXL: 26px;
  --radiusLG: 20px;
  --radiusMD: 14px;
  --radiusSM: 10px;

  --tr: .28s ease;
}

/* =========================================================
   RESET / BASE
   ========================================================= */

html{
  background: #050505 !important;
}

body{
  background: transparent !important;
  color: var(--text) !important;
  position: relative !important;
  min-height: 100vh !important;
}

/* on neutralise les fonds blancs/gris du site */
body,
main,
header,
nav,
section,
article,
footer,
div,
.container,
.container-fluid,
.content,
.content-page,
.catalogue,
.row,
.col,
[class*="container"],
[class*="content"],
[class*="wrapper"],
[class*="page"],
[class*="main"]{
  background-color: transparent !important;
}

/* =========================================================
   FOND GLOBAL — visible, léger, cinématique
   ========================================================= */

html::before{
  content:"";
  position: fixed;
  inset: 0;
  z-index: -99999;
  pointer-events: none;
  background:
    linear-gradient(135deg, rgba(0,0,0,.48), rgba(12,8,5,.36)),
    radial-gradient(circle at 78% 20%, rgba(255,139,71,.14), transparent 24%),
    radial-gradient(circle at 20% 30%, rgba(246,199,110,.10), transparent 28%),
    radial-gradient(circle at 70% 80%, rgba(213,109,45,.08), transparent 26%),
    var(--bg-image) center center / cover no-repeat;
  filter: blur(4px) brightness(.72) saturate(1.06) contrast(1.02);
  transform: scale(1.03);
}

html::after{
  content:"";
  position: fixed;
  inset: 0;
  z-index: -99998;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(0,0,0,.06), rgba(0,0,0,.18)),
    linear-gradient(120deg, rgba(255,191,95,.03), transparent 35%, transparent 70%, rgba(255,125,52,.03));
}

/* =========================================================
   LAYOUT GLOBAL — effet "zoom visuel"
   ========================================================= */

body > *{
  position: relative;
  z-index: 1;
}

/* le site reste lisible mais on laisse plus respirer le fond */
main,
.container,
.container-fluid {
  max-width: 96% !important;
}

/* =========================================================
   HEADER / TOPBAR
   ========================================================= */

header,
nav,
.navbar,
.topbar,
[class*="navbar"],
[class*="header"]{
  background: rgba(8,8,12,.50) !important;
  backdrop-filter: blur(14px) saturate(1.08) !important;
  -webkit-backdrop-filter: blur(14px) saturate(1.08) !important;
  border-bottom: 1px solid var(--border) !important;
  box-shadow: 0 10px 28px rgba(0,0,0,.20) !important;
}

/* boutons / liens du header */
header a,
nav a,
.navbar a,
.topbar a,
header span,
nav span{
  color: #f5ecdf !important;
  transition: var(--tr) !important;
}

header a:hover,
nav a:hover,
.navbar a:hover,
.topbar a:hover{
  color: var(--gold) !important;
  text-shadow: 0 0 10px rgba(255,201,110,.16);
}

/* champ de recherche */
input,
input[type="text"],
input[type="search"],
.search input,
.form-control{
  background: rgba(14,14,18,.62) !important;
  color: var(--text) !important;
  border: 1px solid rgba(255,201,110,.16) !important;
  border-radius: 999px !important;
  box-shadow: none !important;
}

input::placeholder{
  color: var(--muted) !important;
}

input:focus,
input[type="text"]:focus,
input[type="search"]:focus,
.form-control:focus{
  border-color: var(--borderStrong) !important;
  box-shadow:
    0 0 0 1px rgba(255,201,110,.18),
    0 0 20px rgba(255,191,95,.08) !important;
  outline: none !important;
}

/* =========================================================
   HERO / GROS BANNER HOME
   ========================================================= */

/* gros bloc vedette */
[class*="hero"],
[class*="banner"],
[class*="spotlight"],
[class*="slider"],
[class*="carousel"],
.owl-carousel,
.swiper,
.swiper-container {
  background: rgba(8,8,12,.28) !important;
  border: 1px solid rgba(255,201,110,.12) !important;
  border-radius: 28px !important;
  overflow: hidden !important;
  box-shadow:
    0 22px 50px rgba(0,0,0,.36),
    0 0 24px rgba(255,191,95,.06) !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
}

/* image du hero */
[class*="hero"] img,
[class*="banner"] img,
[class*="spotlight"] img,
[class*="slider"] img,
[class*="carousel"] img,
.owl-carousel img,
.swiper img{
  filter: brightness(.92) saturate(1.05) contrast(1.03) !important;
}

/* overlay premium sur le hero */
[class*="hero"]::before,
[class*="banner"]::before,
[class*="spotlight"]::before,
[class*="slider"]::before,
[class*="carousel"]::before,
.owl-carousel::before,
.swiper::before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  z-index:2;
  background:
    linear-gradient(90deg, rgba(0,0,0,.34) 0%, rgba(0,0,0,.12) 42%, rgba(0,0,0,.08) 100%),
    linear-gradient(180deg, rgba(255,255,255,.03), transparent 35%, rgba(0,0,0,.16)),
    linear-gradient(135deg, rgba(255,201,110,.06), transparent 38%, transparent 70%, rgba(255,139,71,.08));
}

/* texte du hero plus lisible */
[class*="hero"] h1,
[class*="banner"] h1,
[class*="spotlight"] h1,
[class*="slider"] h1,
[class*="carousel"] h1,
.owl-carousel h1,
.swiper h1{
  color: #fff6e8 !important;
  text-shadow: 0 4px 18px rgba(0,0,0,.42) !important;
  font-weight: 800 !important;
  letter-spacing: .2px !important;
}

[class*="hero"] p,
[class*="banner"] p,
[class*="spotlight"] p,
[class*="slider"] p,
[class*="carousel"] p,
.owl-carousel p,
.swiper p{
  color: #efe4d3 !important;
  text-shadow: 0 2px 10px rgba(0,0,0,.36) !important;
}

/* boutons du hero */
[class*="hero"] .btn,
[class*="banner"] .btn,
[class*="spotlight"] .btn,
[class*="slider"] .btn,
[class*="carousel"] .btn,
.owl-carousel .btn,
.swiper .btn,
button,
.btn{
  background: linear-gradient(135deg, rgba(246,199,110,.16), rgba(213,109,45,.14)) !important;
  color: #fff6e8 !important;
  border: 1px solid rgba(255,201,110,.18) !important;
  border-radius: 999px !important;
  box-shadow: 0 8px 24px rgba(0,0,0,.22) !important;
  transition: var(--tr) !important;
}

[class*="hero"] .btn:hover,
[class*="banner"] .btn:hover,
[class*="spotlight"] .btn:hover,
[class*="slider"] .btn:hover,
[class*="carousel"] .btn:hover,
.owl-carousel .btn:hover,
.swiper .btn:hover,
button:hover,
.btn:hover{
  transform: translateY(-1px) !important;
  border-color: rgba(255,201,110,.30) !important;
  box-shadow:
    0 12px 28px rgba(0,0,0,.26),
    0 0 16px rgba(255,191,95,.06) !important;
}

/* =========================================================
   SECTIONS / BLOCS HOME
   ========================================================= */

section,
article,
.card,
[class*="card"],
[class*="box"],
[class*="panel"],
[class*="bloc"],
[class*="resume"],
[class*="episode"],
[class*="anime"]{
  color: var(--text) !important;
}

/* gros conteneurs de sections */
section,
article,
[class*="section"],
[class*="content-block"],
[class*="listing"],
[class*="catalogue"],
[class*="resume"]{
  background: rgba(8,8,12,.20) !important;
  border-radius: 22px !important;
}

/* titres de sections */
h1,h2,h3,h4,h5,
.title,
.section-title,
[class*="title"]{
  color: #fff3df !important;
}

/* =========================================================
   CARTES / MINIATURES
   ========================================================= */

.card,
[class*="card"],
[class*="anime-card"],
[class*="media-card"],
[class*="episode-card"],
[class*="watch-card"],
[class*="poster-card"]{
  background: linear-gradient(180deg, rgba(11,14,25,.84), rgba(8,10,18,.92)) !important;
  border: 1px solid rgba(255,201,110,.12) !important;
  border-radius: 20px !important;
  overflow: hidden !important;
  box-shadow: var(--shadowDark) !important;
  transition: transform var(--tr), box-shadow var(--tr), border-color var(--tr) !important;
}

.card:hover,
[class*="card"]:hover,
[class*="anime-card"]:hover,
[class*="media-card"]:hover,
[class*="episode-card"]:hover,
[class*="watch-card"]:hover,
[class*="poster-card"]:hover{
  transform: translateY(-6px) !important;
  border-color: rgba(255,201,110,.26) !important;
  box-shadow:
    0 20px 40px rgba(0,0,0,.34),
    0 0 20px rgba(255,191,95,.06),
    0 0 16px rgba(255,139,71,.04) !important;
}

/* miniatures */
.card img,
[class*="card"] img,
[class*="cover"] img,
[class*="thumb"] img,
[class*="poster"] img{
  border-radius: 16px !important;
  transition: transform .38s ease, filter .38s ease !important;
  filter: saturate(1.08) contrast(1.03) brightness(.98) !important;
}

.card:hover img,
[class*="card"]:hover img,
[class*="cover"]:hover img,
[class*="thumb"]:hover img,
[class*="poster"]:hover img{
  transform: scale(1.045) !important;
  filter: saturate(1.14) contrast(1.05) brightness(1.02) !important;
}

/* overlay premium */
.card [class*="cover"],
.card [class*="thumb"],
.card [class*="poster"],
[class*="cover"],
[class*="thumb"],
[class*="poster"]{
  position: relative !important;
  overflow: hidden !important;
}

.card [class*="cover"]::before,
.card [class*="thumb"]::before,
.card [class*="poster"]::before,
[class*="cover"]::before,
[class*="thumb"]::before,
[class*="poster"]::before{
  content:"";
  position:absolute;
  inset:0;
  z-index:2;
  pointer-events:none;
  background:
    linear-gradient(180deg, rgba(255,255,255,.03), transparent 30%, transparent 60%, rgba(0,0,0,.18)),
    linear-gradient(135deg, rgba(255,201,110,.08), transparent 38%, transparent 72%, rgba(255,139,71,.08));
}

.card [class*="cover"]::after,
.card [class*="thumb"]::after,
.card [class*="poster"]::after,
[class*="cover"]::after,
[class*="thumb"]::after,
[class*="poster"]::after{
  content:"";
  position:absolute;
  inset:0;
  z-index:3;
  border-radius: inherit;
  pointer-events:none;
  box-shadow:
    inset 0 0 0 1px rgba(255,201,110,.14),
    inset 0 -24px 34px rgba(0,0,0,.10);
}

/* texte des cartes */
.card h3,
.card h4,
.card .title,
[class*="card"] h3,
[class*="card"] h4,
[class*="card"] .title{
  color: #fff6e8 !important;
  font-weight: 700 !important;
}

.card p,
.card small,
[class*="card"] p,
[class*="card"] small,
.meta,
.description{
  color: var(--textSoft) !important;
}

/* =========================================================
   BADGES / LANGUES / PETITS LABELS
   ========================================================= */

.badge,
.tag,
.chip,
[class*="badge"],
[class*="tag"],
[class*="lang"],
[class*="label"]{
  background: rgba(7,7,10,.58) !important;
  color: #fff4df !important;
  border: 1px solid rgba(255,201,110,.14) !important;
  border-radius: 999px !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  box-shadow: 0 4px 12px rgba(0,0,0,.14) !important;
}

/* =========================================================
   PAGE ANIME / LECTEUR
   ========================================================= */

/* gros conteneurs page catalogue/lecteur */
[class*="reader"],
[class*="player"],
[class*="video"],
iframe,
video{
  border-radius: 24px !important;
  overflow: hidden !important;
  border: 1px solid rgba(255,201,110,.14) !important;
  box-shadow:
    0 18px 50px rgba(0,0,0,.40),
    0 0 24px rgba(255,191,95,.06) !important;
  background: rgba(8,8,12,.66) !important;
}

/* panneaux épisodes / infos / synopsis */
[class*="episode-list"],
[class*="episodes"],
[class*="sidebar"],
[class*="synopsis"],
[class*="info"],
[class*="details"],
[class*="season"],
[class*="lecteur"],
[class*="watch"]{
  background: rgba(10,10,14,.46) !important;
  border: 1px solid rgba(255,201,110,.12) !important;
  border-radius: 22px !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  box-shadow: 0 16px 38px rgba(0,0,0,.28) !important;
}

/* boutons épisode / serveur / langue */
[class*="episode"] a,
[class*="episode"] button,
[class*="server"] button,
[class*="season"] button,
[class*="watch"] button{
  background: linear-gradient(135deg, rgba(246,199,110,.12), rgba(213,109,45,.10)) !important;
  color: #fff4df !important;
  border: 1px solid rgba(255,201,110,.16) !important;
  border-radius: 14px !important;
}

/* =========================================================
   POPUPS / MENUS / MODALS
   ========================================================= */

.modal,
.dropdown-menu,
.tooltip,
[class*="modal"],
[class*="popup"],
[class*="dropdown"]{
  background: rgba(10,10,14,.82) !important;
  border: 1px solid rgba(255,201,110,.12) !important;
  border-radius: 18px !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
  box-shadow:
    0 18px 40px rgba(0,0,0,.38),
    0 0 20px rgba(255,191,95,.05) !important;
}

/* =========================================================
   LIENS / TEXTES
   ========================================================= */

a{
  color: #ffe1a7 !important;
  transition: var(--tr) !important;
}

a:hover{
  color: #fff2d4 !important;
  text-shadow: 0 0 8px rgba(255,201,110,.14) !important;
}

p, span, li, small{
  color: var(--textSoft) !important;
}

/* =========================================================
   SCROLLBAR
   ========================================================= */

::-webkit-scrollbar{
  width: 10px !important;
  height: 10px !important;
}
::-webkit-scrollbar-track{
  background: rgba(0,0,0,.20) !important;
}
::-webkit-scrollbar-thumb{
  background: linear-gradient(180deg, rgba(246,199,110,.72), rgba(213,109,45,.68)) !important;
  border-radius: 999px !important;
  border: 2px solid rgba(10,10,10,.28) !important;
}
::-webkit-scrollbar-thumb:hover{
  background: linear-gradient(180deg, rgba(255,210,126,.90), rgba(255,125,52,.88)) !important;
}

/* =========================================================
   CORRECTIONS SPÉCIALES HOME
   ========================================================= */

/* la grosse zone grise / blanche derrière les cartes :
   on la rend transparente ou en verre sombre */
.row,
[class*="row"],
[class*="content"],
[class*="list"],
[class*="grid"]{
  background-color: transparent !important;
}

/* si certains gros blocs restent gris */
div[style*="background"],
section[style*="background"]{
  background-color: transparent !important;
}

/* =========================================================
   PETIT BOOST VISUEL
   ========================================================= */

.card,
[class*="card"],
[class*="episode"],
[class*="anime"],
[class*="banner"],
[class*="hero"]{
  will-change: transform;
}
}
